static void Main(string[] args)
{
    // Set the attacking and defensive abilities of each team
    double team1Attack = 1.5;
    double team1Defense = 0.8;
    double team2Attack = 1.2;
    double team2Defense = 1.0;

    // Define the state space for the game
    var states = Enumerable.Range(0, 6)
        .SelectMany(homeScore => Enumerable.Range(0, 6)
            .Select(awayScore => new { HomeScore = homeScore, AwayScore = awayScore }))
        .ToArray();

    // Define the transition matrix for the game
    var transitionMatrix = GetTransitionMatrix(states, team1Attack, team1Defense, team2Attack, team2Defense);

    // Simulate the game using the MCMC method
    var random = new Random();
    var currentState = new { HomeScore = 0, AwayScore = 0 };
    const int numIterations = 100000;
    var stateCounts = new int[states.Length];
    for (int i = 0; i < numIterations; i++)
    {
        // Get the probabilities of transitioning to each possible state
        var transitionProbabilities = transitionMatrix
            .Where(t => t.HomeScore == currentState.HomeScore && t.AwayScore == currentState.AwayScore)
            .Select(t => t.Probability)
            .ToArray();

        // Choose the next state based on the probabilities
        var cumulativeProbabilities = new double[transitionProbabilities.Length];
        double cumulativeProbability = 0.0;
        for (int j = 0; j < transitionProbabilities.Length; j++)
        {
            cumulativeProbability += transitionProbabilities[j];
            cumulativeProbabilities[j] = cumulativeProbability;
        }
        double randomValue = random.NextDouble();
        int nextStateIndex = Array.BinarySearch(cumulativeProbabilities, randomValue);
        if (nextStateIndex < 0)
        {
            nextStateIndex = ~nextStateIndex;
        }
        var nextState = states[nextStateIndex];

        // Record the state count
        int stateIndex = Array.IndexOf(states, nextState);
        stateCounts[stateIndex]++;

        // Update the current state
        currentState = nextState;
    }

    // Get the probability of each final score
    var probabilities = stateCounts
        .Select(count => (double)count / numIterations)
        .ToArray();

    // Print the probabilities of each final score
    for (int i = 0; i < states.Length; i++)
    {
        Console.WriteLine($"{states[i].HomeScore}-{states[i].AwayScore}: {probabilities[i]:P2}");
    }
}
